const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Boston, MA
  const boston = ee.Geometry.Point([-71.06, 42.36]);

  // 2. Define date range
  const startDate = '2019-01-29';
  const endDate = '2019-02-06'; // Inclusive of Feb 5

  // 3. Load ERA5-Land Daily Aggregated data
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
    .filterDate(startDate, endDate)
    .filterBounds(boston)
    .select('temperature_2m_max'); // Maximum daily temperature at 2m

  // 4. Check collection size
  const collectionSize = era5.size().getInfo();
  console.log(`Collection size: ${collectionSize} images`);

  if (collectionSize === 0) {
    console.log("No data found for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Extract temperature values for each day
  const imageList = era5.toList(collectionSize);
  let temperatures = [];
  let validCount = 0;

  for (let i = 0; i < collectionSize; i++) {
    const image = ee.Image(imageList.get(i));
    const date = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();

    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: boston,
      scale: 11132,
      maxPixels: 1e9
    });

    const tempKelvin = stats.get('temperature_2m_max').getInfo();

    if (tempKelvin !== null && tempKelvin !== undefined) {
      const tempCelsius = tempKelvin - 273.15;
      temperatures.push(tempCelsius);
      console.log(`${date}: ${tempCelsius.toFixed(2)}°C`);
      validCount++;
    }
  }

  // 6. Check if we have valid data
  if (validCount === 0) {
    console.log("No valid temperature values retrieved.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Find max and min temperatures
  const maxTemp = Math.max(...temperatures);
  const minTemp = Math.min(...temperatures);
  const difference = maxTemp - minTemp;

  console.log(`\nHighest daily max temp: ${maxTemp.toFixed(2)}°C`);
  console.log(`Lowest daily max temp: ${minTemp.toFixed(2)}°C`);
  console.log(`Temperature difference: ${difference.toFixed(2)}°C`);

  // 8. Validate temperatures are realistic
  if (maxTemp > 60 || minTemp < -60) {
    console.log("Temperature values outside realistic range.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 9. Final answer
  if (difference >= 30) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
